Translate("deDE", "the-deadmines", {
	title = "Die Todesminen",
	aliases = { "Todesminen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Todesminen liegen unter dem Dorf {link:moonbrook}Moonbrook{/link} in {link:westfall}Westfall{/link}. Einst waren sie die reichsten Goldminen in den Ländern der {link:humans}Menschen{/link}. Heute sind sie das geheime Herz der {link:defias-brotherhood}Bruderschaft der Defias{/link}. In ihren Tiefen bauen die Steinmetze von {link:edwin-vancleef}Edwin VanCleef{/link} und die Goblins, die sie angeheuert haben, etwas, das in {link:stormwind-city}Stormwind{/link} noch niemand gesehen hat: ein großes Kriegsschiff, verborgen in einer Meereshöhle am Grund der Minen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Über Generationen schickten die Minen unter {link:moonbrook}Moonbrook{/link} Gold in die Schatzkammer des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}. Als die {link:horde}Horde{/link} {link:stormwind-city}Stormwind{/link} im {link:first-war}Ersten Krieg{/link} niederbrannte, flohen die Bergleute, und die Arbeit verstummte. Die Stollen wurden der Dunkelheit überlassen, und das Volk begann, sie die Todesminen zu nennen. Durch die Jahre des Exils und des Wiederaufbaus blieben sie leer. Als die verratenen Steinmetze nach Westen kamen, fanden sie eine Festung vor, die schon für sie gegraben war.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Bruderschaft hat die alte Mine zu ihrem Heiligtum gemacht. Bergleute der {link:defias-brotherhood}Defias{/link} graben in ihren Schächten, und Zauberer und Beschwörer der Bruderschaft bewachen ihre Hallen. Goblinhandwerker und Ingenieure im Sold der Bruderschaft schlagen Holz, schmelzen Metall und bauen Maschinen. Ein {link:ogres}Oger{/link} hütet das erste Tor. Tief unten, wo sich die Stollen zum Meer öffnen, ist das Schiff beinahe fertig, und sein Kapitän und seine Mannschaft warten auf den Befehl ihres Herrn. Was {link:edwin-vancleef}VanCleef{/link} damit vorhat, weiß nur die Bruderschaft. Viele fürchten, es sei für {link:stormwind-city}Stormwind{/link} bestimmt.]=],
		},
		{
			title = "In den Minen",
			text = [=[• {b}Der eingestürzte Flügel.{/b} Vor dem Eingang der Bruderschaft führt ein Seitengang zu Stollen, in denen eine Gruppe zwergischer Bergleute und Forscher verschüttet wurde, als die Decke einstürzte. Sie finden keine Ruhe. Ihre Toten wandeln noch immer mit Spitzhacken und Dynamit durch die Dunkelheit.
• {b}Die Mastkammer.{/b} Hier schlagen die Goblins des Holzmeisters {link:sneed}Sneed{/link} große Balken für das Schiff.
• {b}Die Gießerei.{/b} Hier schmilzt der Goblin {link:gilnid}Gilnid{/link} das Metall der Minen.
• {b}Die {link:ironclad-cove}Ironcladbucht{/link}.{/b} Am Grund der Minen liegt eine zum Meer offene Höhle, in der das Schiff der Bruderschaft vor Anker liegt. Ihr Tor ist versiegelt, und nur Pulver und Kanone werden es öffnen.
• {b}Der verborgene Ausgang.{/b} Von der Bucht steigt ein Gang zu den Hügeln hinter {link:moonbrook}Moonbrook{/link} hinauf, nahe am Meer.]=],
		},
		{
			title = "Die Bewohner der Tiefe",
			text = [=[Die Diener der Bruderschaft sind hier zahlreich. Der Vorarbeiter {link:rhahkzor}Rhahk'Zor{/link}, die Goblins {link:sneed}Sneed{/link} und {link:gilnid}Gilnid{/link} und die Schiffsmannschaft unter {link:captain-greenskin}Kapitän Greenskin{/link} gehorchen alle {link:edwin-vancleef}Edwin VanCleef{/link}. Seltenere Gefahren lauern ebenfalls in den Stollen, unter ihnen ein Bergmann von großer Kraft, bekannt als Bergmann Johnson.]=],
		},
	},
})

Translate("deDE", "ironclad-cove", {
	title = "Ironcladbucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ironcladbucht ist eine gewaltige Meereshöhle am Grund der {link:the-deadmines}Todesminen{/link}, wo die Stollen der alten Goldminen zum Großen Meer durchbrechen. Hier hütet die {link:defias-brotherhood}Bruderschaft der Defias{/link} ihr größtes Geheimnis. Auf dem dunklen Wasser liegt ein Kriegsschiff vor Anker, gebaut aus Holz, das in der Mastkammer geschlagen, und Metall, das in der Gießerei geschmolzen wurde. Piraten der Bruderschaft bilden seine Mannschaft. Von seinem Oberdeck aus befehligt {link:edwin-vancleef}Edwin VanCleef{/link} seine ganze Bruderschaft, und hier hat er beschlossen, sich zu stellen.]=],
		},
	},
})

Translate("deDE", "edwin-vancleef", {
	title = "Edwin VanCleef",
	subtitle = "Anführer der Bruderschaft der Defias",
	found = "Das Oberdeck des Schiffes in der Ironcladbucht",
	hint = [=[Erfahrt von ihm bei der Miliz von Westfall, oder sucht ihn am Grund der Todesminen.]=],
	allegiance = "Bruderschaft der Defias · einst die Steinmetzgilde",
	aliases = { "VanCleef", "Edwin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Edwin VanCleef war der Meister der {link:stonemasons-guild}Steinmetzgilde{/link} von {link:stormwind-city}Stormwind{/link}. Seine Gilde war es, die die {link:capital-city}Hauptstadt{/link} aus der Asche des {link:first-war}Ersten Krieges{/link} wieder errichtete. Als die Arbeit getan war, weigerte sich das {link:house-of-nobles}Haus der Adligen{/link}, den Steinmetzen zu zahlen, was man ihnen schuldete. VanCleef führte sie in den Aufstand und verließ die Stadt mit einem Schwur der Rache. Heute ist er der Anführer der {link:defias-brotherhood}Bruderschaft der Defias{/link}, Herr über {link:westfall}Westfall{/link}, und aus einer verborgenen Bucht unter der Erde bereitet er seinen Schlag gegen das Königreich vor, das ihn verraten hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[VanCleef ist die Wunde, die {link:stormwind-city}Stormwind{/link} sich selbst zugefügt hat. Er war ein Baumeister, kein Bandit, und wer ihn kannte, erinnert sich an einen begabten und fleißigen Mann. Seine Bruderschaft entstand aus einem echten Unrecht. Doch seine Rache hat am härtesten das einfache Volk von {link:westfall}Westfall{/link} getroffen, nicht die Adligen, die ihn betrogen, und sie hat die Kornkammer des Königreichs selbst in den Ruin getrieben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die {link:stonemasons-guild}Steinmetzgilde{/link} beim Wiederaufbau Stormwinds nach den Kriegen.
• Als einigen älteren Steinmetzen Ämter in der Regierung angeboten wurden, lehnte er sein eigenes aus Treue zur ganzen Gilde ab.
• Er führte den Aufstand der Steinmetze an und floh an dessen Ende aus der Stadt. Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} kam in dem Chaos ums Leben.
• Er sammelte die verbannten Steinmetze in {link:westfall}Westfall{/link} und gründete die {link:defias-brotherhood}Bruderschaft der Defias{/link}.
• Er nahm die {link:the-deadmines}Todesminen{/link} zu seiner Festung und heuerte Goblins an, um in ihren Tiefen ein Kriegsschiff zu bauen.
• Sein Leutnant, {link:bazil-thredd}Bazil Thredd{/link}, wurde gefasst und in {link:the-stockade}das Verlies{/link} von {link:stormwind-city}Stormwind{/link} gesperrt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet VanCleefs Geburt, seine Familie oder die Jahre, bevor er Meister der Gilde wurde. Dieser Eintrag verzeichnet nur seine Taten und die Worte derer, die ihn kannten.]=],
		},
	},
	chapters = {
		{
			title = "Ein Name aus der Vergangenheit",
			hint = "Tragt die Frage nach den Steinmetzen zu SI:7.",
			text = [=[Lange hatte die Bruderschaft kein Gesicht. Dann gab ihr {link:master-mathias-shaw}Mathias Shaw{/link} von {link:si-7}SI:7{/link} eines. Die alte Gilde der Steinmetze, schrieb er, wurde von einem Mann namens Edwin VanCleef geführt, einem Mann, der {link:stormwind-city}Stormwind{/link} wieder aufgebaut hatte und dafür keinen Dank erhielt.]=],
		},
		{
			title = "Der Brief des Boten",
			hint = [=[Fangt den Boten der Bruderschaft auf den Straßen von Westfall ab.]=],
			text = [=[Ein Bote der {link:defias-brotherhood}Defias{/link} ritt die Straßen zwischen {link:moonbrook}Moonbrook{/link}, dem Steinbruch und dem {link:jangolode-mine}Jangoschacht{/link}. Die Nachricht, die er trug, war ein fester Beweis, dass die Bruderschaft VanCleef gehorchte. Wo er sich verbarg, sagte sie nicht.]=],
		},
		{
			title = "Das Versteck",
			hint = [=[Folgt dem Verräter der Defias zum Unterschlupf der Bruderschaft.]=],
			text = [=[Ein gefangener Dieb erkaufte sich sein Leben, indem er die Miliz nach {link:moonbrook}Moonbrook{/link} führte. Unter dem Dorf, in der alten Goldmine, warteten VanCleef und seine Steinmetze.]=],
		},
		{
			title = "Der Fall des Anführers",
			hint = "Steigt hinab zum Grund der Todesminen.",
			text = [=[Am Grund der Minen, auf dem Deck seines Schiffes, trat VanCleef denen entgegen, die gekommen waren, ihn zu holen. Er ergab sich nicht. Er rief seine Wachen an seine Seite und kämpfte ohnegleichen, so wie {link:baros-alexston}Baros Alexston{/link} ihn aus seinen jüngeren Jahren kämpfen gesehen hatte. Als er fiel, wurde sein Kopf zur {link:sentinel-hill}Späherkuppe{/link} zurückgebracht.]=],
		},
		{
			title = "Der nie abgeschickte Brief",
			hint = "Durchsucht VanCleefs Habe und überbringt, was ihr findet.",
			text = [=[Unter VanCleefs Habe fand sich ein versiegelter Brief, nie abgeschickt, gerichtet an {link:baros-alexston}Baros Alexston{/link}, den Stadtarchitekten von {link:stormwind-city}Stormwind{/link}. Baros hatte ihn in der Gilde gekannt. Als er ihn las, nannte er VanCleef noch immer einen Idealisten und Romantiker, einen Mann, den die Rache verzehrt hatte. Er gestand auch, dass er ihm nicht ganz die Schuld geben konnte.]=],
		},
	},
	mentions = {
		{
			text = [=[Die {link:defias-brotherhood}Bruderschaft der Defias{/link}, die Notiz des Schurken]=],
		},
		{
			text = [=[Die {link:defias-brotherhood}Bruderschaft der Defias{/link}, zu {link:master-mathias-shaw}Mathias Shaw{/link} gebracht]=],
		},
		{
			text = [=[{link:bazil-thredd}Bazil Thredd{/link}, von {link:baros-alexston}Baros Alexston{/link}]=],
		},
		{ text = "Red Silk Bandanas" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "jagt ihn" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "einst ein Steinmetz seiner Gilde" },
		{ id = "bazil-thredd", name = "Bazil Thredd", note = "sein Leutnant" },
		{ id = "master-mathias-shaw", name = "Meister Mathias Shaw", note = "nannte seinen Namen" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "starb in dem Aufstand, den er anführte" },
		{ id = "captain-greenskin", name = "Kapitän Greenskin", note = "Kapitän seines Schiffes" },
		{ id = "the-defias-traitor", name = "Der Verräter der Defias", note = "verriet ihn" },
	},
})

Translate("deDE", "rhahkzor", {
	title = "Rhahk'Zor",
	subtitle = "Der Vorarbeiter",
	found = "Das erste Tor der Todesminen",
	hint = "Stellt Euch dem Oger, der das erste Tor der Minen bewacht.",
	allegiance = "Bruderschaft der Defias",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rhahk'Zor ist ein {link:ogres}Oger{/link} im Sold der {link:defias-brotherhood}Bruderschaft der Defias{/link} und der Vorarbeiter ihrer Minen. Er hütet das erste Tor der {link:the-deadmines}Todesminen{/link}. Seine Aufgabe ist es, jeden Eindringling aufzuhalten, der durch die Stollen kommt, und er prahlt, dass {link:edwin-vancleef}VanCleef{/link} für jeden Kopf gut bezahlt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rhahk'Zor zeigt, wie weit die Bruderschaft nach Verbündeten gegriffen hat. Steinmetze, die einst für einen König bauten, halten sich nun einen {link:ogres}Oger{/link} an ihrer Tür.]=],
		},
		{
			title = "Taten",
			text = [=[• Er treibt die Bergleute der {link:defias-brotherhood}Defias{/link} bei ihrer Arbeit an.
• Er bewacht das Tor zwischen der oberen Mine und den Hallen der Bruderschaft.]=],
		},
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "bezahlt ihn" },
	},
})

