		},
		{
			title = "Taten",
			text = [=[• Er überwacht das Schlagen der Schiffsbalken.
• Er lenkt den einzigen funktionierenden Schredder in den {link:the-deadmines}Todesminen{/link}.]=],
		},
	},
	mentions = {
		{ text = "Underground Assault" },
	},
	bonds = {
		{ id = "gilnid", name = "Gilnid", note = "ein Goblin wie er in den Werken" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "sein Auftraggeber" },
	},
})

