			title = "Bedeutung",
			text = [=[Ein {link:tauren}Tauren{/link} unter den {link:defias-brotherhood}Defias{/link} ist ein seltsamer Anblick. Was auch immer ihn so weit von den Ebenen seines Volkes fortgeführt hat, er dient nun VanCleefs Schiff mit all seiner Kraft.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligt die Mannschaft im Namen von {link:captain-greenskin}Kapitän Greenskin{/link}.
• Er bewacht die Docks, an denen das Schiff vor Anker liegt.]=],
		},
	},
	bonds = {
		{ id = "captain-greenskin", name = "Kapitän Greenskin", note = "sein Kapitän" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "sein Herr" },
	},
})

