Translate("deDE", "foreman-thistlenettle", {
	title = "Vorarbeiter Thistlenettle",
	subtitle = "Verschollener Vorarbeiter der Forscherliga",
	found = "Der eingestürzte Flügel vor dem Tor der Bruderschaft",
	hint = [=[Stellt Euch dem untoten Zwerg in den eingestürzten Stollen der Todesminen.]=],
	allegiance = "Forscherliga (einst)",
	aliases = { "Thistlenettle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vorarbeiter Thistlenettle war ein {link:dwarves}Zwerg{/link} der {link:explorers-league}Forscherliga{/link}, der einen Trupp tief in die gewaltige Mine unter {link:moonbrook}Moonbrook{/link} führte. Diebe tauchten in den Stollen auf, und dann stürzte der Stollen ein. Sein Bruder Wilder kam heraus. Von dem Vorarbeiter und seinem Trupp hörte man nie wieder. Nun wandelt er als einer der Toten durch die dunklen Stollen, unter den Bergleuten, die mit ihm verschüttet wurden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thistlenettle ist ein Opfer der {link:the-deadmines}Todesminen{/link}, noch bevor man das Tor der Bruderschaft erreicht. Sein Bruder wartet in {link:stormwind-city}Stormwind{/link} auf jede Nachricht von ihm.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte den zwergischen Trupp in der Mine unter {link:moonbrook}Moonbrook{/link}.
• Er trug stets sein Abzeichen der {link:explorers-league}Forscherliga{/link}.]=],
		},
	},
	mentions = {
		{ text = "Oh Brother..." },
		{ text = "Collecting Memories" },
	},
	bonds = {
		{ id = "wilder-thistlenettle", name = "Wilder Thistlenettle", note = "sein Bruder" },
	},
})
